using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Drawing;using System.Windows.Forms;
class WordExampleChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool value,string label){if(!value)throw new Exception(label);}
 static object Call(Game game,string method,params object[] args){return typeof(Game).GetMethod(method,Flags).Invoke(game,args);}
 static IEnumerable<Control> All(Control root){yield return root;foreach(Control child in root.Controls)foreach(var item in All(child))yield return item;}
 static string Pages(Form popup){return All(popup).OfType<OutlinedLabel>().First(x=>x.Dock==DockStyle.Fill).Text;}
 [STAThread]static void Main(string[] args){try{
  var rows=Engine.Json.Deserialize<Dictionary<string,List<BilingualWordExample>>>(File.ReadAllText(Path.Combine(args[0],"assets/word-examples.json")));
  Check(rows.Count>5000,"examples loaded");Check(rows.All(r=>r.Value.Count>=1&&r.Value.Count<=2&&r.Value.All(e=>!String.IsNullOrWhiteSpace(e.english)&&!String.IsNullOrWhiteSpace(e.chinese))),"bilingual pairs complete");
  Check(rows.All(r=>r.Value.Select(e=>e.english.ToLowerInvariant()).Distinct().Count()==r.Value.Count),"English examples deduplicated");
  using(var game=new Game()){
   game.Show();Application.DoEvents();var save=(Save)typeof(Game).GetField("save",Flags).GetValue(game);int wordCount=save.words.Count,coins=save.rogue.coins;
   Check(((List<RogueEntry>)Call(game,"TrainingPool","四级训练")).Count==4371,"CET4 training unchanged");Check(((List<RogueEntry>)Call(game,"TrainingPool","六级训练")).Count==2610,"CET6 training unchanged");
   Check(((List<BilingualWordExample>)Call(game,"ImportedWordExamples","ABILITY")).Count>0,"case-insensitive lookup");
   string meaning="保留原有释义",context="Keep this original contextual example.";
   Call(game,"ShowSpellWord","abandon",meaning,context,"",false);Application.DoEvents();var popup=Application.OpenForms.Cast<Form>().First(f=>f!=game&&f.Text.StartsWith("单词释义"));
   Check(!All(popup).OfType<ScrollableControl>().Any(c=>c.AutoScroll),"popup avoids native scrollbars");var definition=All(popup).OfType<OutlinedLabel>().First(x=>x.Dock==DockStyle.Fill);Check(!All(popup).OfType<VNButton>().Any(x=>new[]{"上一页","下一页","关闭"}.Contains(x.Text)),"no footer buttons");using(var preview=new Bitmap(popup.Width,popup.Height)){popup.DrawToBitmap(preview,new Rectangle(0,0,popup.Width,popup.Height));preview.Save(Path.Combine(args[0],".validation/word-examples-popup.png"));}
   string content=Pages(popup);Check(content.Contains(meaning)&&content.Contains(context),"meaning and contextual example retained");
   Check(!content.Contains("【例句 1】"),"one contextual example only");
   popup.Size=new Size(520,430);Application.DoEvents();Check(Pages(popup)==content,"one page retains content after resize");Check(TextRenderer.MeasureText(content,definition.Font,new Size(definition.Width-12,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPadding).Height<=definition.Height,"one page fits resized popup");
   popup.DrawToBitmap(new Bitmap(popup.Width,popup.Height),new Rectangle(0,0,popup.Width,popup.Height));popup.Close();
   Call(game,"AddWord","ability","");Application.DoEvents();popup=Application.OpenForms.Cast<Form>().First(f=>f!=game&&f.Text.StartsWith("单词释义"));content=Pages(popup);Check(content.Contains(rows["ability"].OrderBy(e=>e.english.Length+e.chinese.Length).First().english)&&content.Contains(rows["ability"].OrderBy(e=>e.english.Length+e.chinese.Length).First().chinese),"story lookup shares bilingual popup");popup.Close();
   var run=new RogueRun{question=new RogueQuestion{entry=new RogueEntry{word="ability",meaning="能力",example="",exampleZh=""}},feedback="回答正确\nability · 能力\n"};
   var originalEntry=Engine.Json.Serialize(run.question.entry);content=(string)Call(game,"RogueFeedbackText",run);Check(content.Contains(rows["ability"][0].english)&&content.Contains(rows["ability"][0].chinese),"feedback includes imported bilingual example");Check(originalEntry==Engine.Json.Serialize(run.question.entry),"feedback does not mutate question entry");
   run.question.entry.example="Original {ability} example.";run.question.entry.exampleZh="原有剧情例句翻译";run.feedback="回答正确\nability · 能力\nOriginal ability example.";content=(string)Call(game,"RogueFeedbackText",run);Check(content.Contains("原有剧情例句翻译")&&!content.Contains(rows["ability"][0].english),"existing training context retains priority");
   Call(game,"ShowSpellWord","zzzmissingexample","仍然可以查词","","",false);Application.DoEvents();popup=Application.OpenForms.Cast<Form>().First(f=>f!=game&&f.Text.StartsWith("单词释义"));Check(Pages(popup).Contains("仍然可以查词"),"unmatched word remains usable");popup.Close();
   Check(save.words.Count==wordCount&&save.rogue.coins==coins,"lookup and feedback preserve saves");
   string allSenses=(string)Call(game,"VocabularySettlementText",new RogueEntry{word="zzztestmeanings",meaning="n. 第一义，第二义，第三义；v. 第四义",example=""});Check(allSenses.Contains("第三义")&&allSenses.Contains("第四义"),"settlement retains meanings after commas and semicolons");
   string threshold=(string)Call(game,"VocabularySettlementText",new RogueEntry{word="threshold",meaning="n.开始,开端,极限",example=""});Check(threshold.Contains("门槛")&&threshold.Contains("阈值"),"old threshold question receives entrance and level senses");
   string hail=(string)Call(game,"VocabularySettlementText",new RogueEntry{word="hail",meaning="n. 冰雹，致敬",example=""});Check(hail.Contains("招呼")&&hail.Contains("冰雹"),"stale training meaning receives common verb sense");
   foreach(string word in new[]{"resign","pursue"}){var pair=rows[word][0];var result=(string)Call(game,"VocabularySettlementText",new RogueEntry{word=word,meaning="保留释义",example=""});Check(result.Contains(pair.english)&&result.Contains(pair.chinese),word+" settlement has bilingual example");}
   using(var panel=new Panel{Size=new Size(430,650)}){game.Controls.Add(panel);var state=new TavernHallState{wordQuestion=new RogueQuestion{kind=0,answered=true,entry=new RogueEntry{word="resign",meaning="v. 辞职",example=""},options=new List<string>()},guidanceFeedback="回答正确\n复习通过"};Call(game,"BuildHallGuidancePractice",panel,state);Application.DoEvents();var result=All(panel).OfType<HallPagedText>().First(x=>x.Content.Contains("例句译文"));Check(result.Content.Contains(rows["resign"][0].english),"guidance settlement wired to example lookup");var next=All(panel).OfType<VNButton>().First(x=>x.Text.StartsWith("继续"));Check(next.Bottom<=panel.Height,"guidance continue button remains visible");panel.Size=new Size(290,430);Application.DoEvents();Check(next.Bottom<=panel.Height,"small guidance settlement remains reachable");typeof(Game).GetField("page",Flags).SetValue(game,"tavern-hall");Check(All(panel).OfType<Label>().Any(x=>x.Text==(string)Call(game,"WordPhonetic","resign")),"guidance settlement has dictionary phonetic");int serial=state.guidanceSerial;var star=All(panel).OfType<RogueIcon>().First(x=>x.Kind=="star");bool selected=star.Selected;star.Focus();Check((bool)Call(game,"ProcessCmdKey",new Message(),Keys.Enter),"settlement consumes Enter");Check(state.guidanceSerial==serial+1&&star.Selected==selected,"Enter continues exactly once instead of favorite");state.guidanceFeedback="回答正确";Call(game,"BuildHallGuidancePractice",new Panel(),new TavernHallState());Check(!(bool)((Func<bool>)typeof(Game).GetField("hallGuidanceEnter",Flags).GetValue(game))(),"hidden view does not continue");game.Controls.Remove(panel);}
   game.Close();
  }
  Console.WriteLine("PASS: bilingual data, unchanged training, contextual priority, feedback, saved progress, single-page popup without footer buttons and resize.");
 }catch(Exception error){Console.WriteLine(error);Environment.Exit(1);}}
}
